package dev.tacticalcombat.client.ui;

import com.google.gson.*;
import dev.tacticalcombat.rules.srd.*;
import dev.tacticalcombat.uiapi.SheetSections;
import java.util.*;
import static dev.tacticalcombat.client.ui.ManagementState.*;

/** Pure post-creation projection. Authoritative and recorded values stay visibly separate. */
public final class DashboardModel {
    public enum Tab { SHEET, SKILLS, INVENTORY, FEATURES, SPELLS, BACKGROUND }
    public record Xp(int level,long value,String mode,long lower,long upper,double fraction,String label) {}
    public record Stat(String label,String value,String authority) {}
    // 2014 cumulative thresholds for reaching levels 1–20.
    public static final long[] XP={0,300,900,2700,6500,14000,23000,34000,48000,64000,85000,100000,120000,140000,165000,195000,225000,265000,305000,355000};
    private static final List<String> ABILITIES=List.of("str","dex","con","int","wis","cha");
    static final Map<String,String> SKILLS=Map.ofEntries(Map.entry("Athletics","str"),Map.entry("Acrobatics","dex"),Map.entry("Sleight of Hand","dex"),Map.entry("Stealth","dex"),Map.entry("Arcana","int"),Map.entry("History","int"),Map.entry("Investigation","int"),Map.entry("Nature","int"),Map.entry("Religion","int"),Map.entry("Animal Handling","wis"),Map.entry("Insight","wis"),Map.entry("Medicine","wis"),Map.entry("Perception","wis"),Map.entry("Survival","wis"),Map.entry("Deception","cha"),Map.entry("Intimidation","cha"),Map.entry("Performance","cha"),Map.entry("Persuasion","cha"));
    private DashboardModel() {}
    public static String title(Tab tab){return switch(tab){case SHEET->"Character Sheet";case SKILLS->"Skills & Saving Throws";case INVENTORY->"Inventory & Equipment";case FEATURES->"Features";case SPELLS->"Spells";case BACKGROUND->"Character Background";};}
    public static UiLayout.Rect listArea(UiLayout.Rect frame){int top=frame.height()<190?62:104;return new UiLayout.Rect(frame.x()+12,frame.y()+top,frame.width()-24,Math.max(24,frame.height()-top-34));}
    public static Xp xp(JsonObject sheet){JsonObject p=SheetSections.read(sheet,"progression");int level=p.get("recordedLevel").getAsInt();long value=p.get("xp").getAsLong();String mode=text(p,"mode");if(!mode.equals("XP"))return new Xp(level,value,mode,0,0,0,mode.equals("MILESTONE")?"Milestone advancement · level "+level:"DM-managed advancement · level "+level);long lower=XP[level-1],upper=level==20?XP[19]:XP[level];double f=level==20?1:Math.clamp((double)(value-lower)/(upper-lower),0,1);String label=level==20?value+" XP · level 20":value+" XP · "+Math.max(0,value-lower)+" / "+(upper-lower)+" toward level "+(level+1);return new Xp(level,value,mode,lower,upper,f,label);}
    /** A present but unsupported projection must not silently fall back to unrelated local formulas. */
    public static JsonObject rules(JsonObject snapshot){
        if(!snapshot.has("rules"))return null;
        var r=snapshot.getAsJsonObject("rules");
        if(!flag(r,"valid")||!r.has("version")||r.get("version").getAsInt()!=CharacterRules.PROJECTION_VERSION)throw new IllegalArgumentException("Rules projection unavailable; Refresh or update Cubetable.");
        return r;
    }
    public static int score(JsonObject snapshot,String ability){var r=rules(snapshot);return r!=null?r.getAsJsonObject("abilities").getAsJsonObject(ability).get("score").getAsInt():SrdAuthoring.data(snapshot.getAsJsonObject("sheet")).getAsJsonObject("abilities").get(ability).getAsInt();}
    public static int modifier(JsonObject snapshot,String ability){var r=rules(snapshot);return r!=null?r.getAsJsonObject("abilities").getAsJsonObject(ability).get("modifier").getAsInt():WizardModel.modifier(score(snapshot,ability));}
    public static String levelNotice(JsonObject snapshot){try{var r=rules(snapshot);return r==null?"":text(r,"levelNotice");}catch(RuntimeException invalid){return "Rules projection unavailable; Refresh or update Cubetable.";}}
    private static String provenance(JsonObject r,String key){var out=new ArrayList<String>();out.add("Server-derived legacy compatibility value");var sources=r.getAsJsonObject("provenance");if(sources!=null)for(var row:array(sources,key))out.add(text(row.getAsJsonObject(),"explanation"));return String.join("\n",out);}
    public static List<Stat> combat(JsonObject snapshot,boolean library){var out=new ArrayList<Stat>();try{var r=rules(snapshot);if(r!=null){add(out,"HP",text(r,"hp")+" / "+text(r,"maximumHp"),provenance(r,"hp"));add(out,"Temporary HP",text(r,"temporaryHp"),provenance(r,"hp"));add(out,"Armor Class",text(r,"ac"),provenance(r,"ac"));add(out,"Initiative",signed(r.get("initiativeModifier").getAsInt()),provenance(r,"initiativeModifier"));add(out,"Speed",text(r,"speedFeet")+" ft",provenance(r,"speedFeet"));add(out,"Proficiency bonus",signed(r.get("proficiency").getAsInt()),provenance(r,"proficiency"));return List.copyOf(out);}}catch(RuntimeException unavailable){return List.of();}JsonObject srd=snapshot.getAsJsonObject("srd");if(srd!=null&&flag(srd,"valid")){add(out,"HP",text(srd,"hp")+" / "+text(srd,"maximumHp"),"Server-authoritative snapshot");add(out,"Temporary HP",text(srd,"temporaryHp"),"Server-authoritative snapshot");add(out,"Armor Class",text(srd,"ac"),"Server-authoritative derived value");add(out,"Initiative",signed(srd.get("initiativeModifier").getAsInt()),"Server-authoritative derived value");add(out,"Speed",text(srd,"speedFeet")+" ft","Server-authoritative derived value");try{add(out,"Proficiency bonus",signed(SrdCharacterCodec.parseSheet(snapshot.getAsJsonObject("sheet").toString()).proficiency()),"Existing SRD rules engine");}catch(RuntimeException ignored){}return out;}if(text(snapshot,"profile").equals("srd_5_1"))try{var c=SrdCharacterCodec.parseSheet(snapshot.getAsJsonObject("sheet").toString());add(out,"HP",c.hp()+" / "+c.maximumHp(),library?"Saved library input":"Effective server sheet");add(out,"Temporary HP",Integer.toString(c.temporaryHp()),"Saved input");add(out,"Armor Class",Integer.toString(c.armorClass()),"Derived by existing SRD codec");add(out,"Initiative",signed(c.modifier(SrdCharacter.Ability.DEX)+c.initiativeBonus()),"Derived by existing SRD codec");add(out,"Speed",c.walkingSpeedFeet()+" ft","Derived by existing SRD codec");add(out,"Proficiency bonus",signed(c.proficiency()),"Existing SRD rules engine");}catch(RuntimeException ignored){}return out;}
    public static List<Stat> abilities(JsonObject snapshot){var out=new ArrayList<Stat>();if(!text(snapshot,"profile").equals("srd_5_1"))return out;try{JsonObject data=SrdAuthoring.data(snapshot.getAsJsonObject("sheet")),scores=data.getAsJsonObject("abilities"),p=SheetSections.read(snapshot.getAsJsonObject("sheet"),"proficiencies");var saves=lower(strings(p,"saves"));for(String key:ABILITIES){int score=scores.get(key).getAsInt();boolean recorded=saves.contains(key)||saves.contains(full(key).toLowerCase(Locale.ROOT));add(out,key.toUpperCase(Locale.ROOT),score+" ("+signed(WizardModel.modifier(score))+") · save "+signed(WizardModel.modifier(score))+(recorded?" · recorded proficiency":""),"Canonical score; recorded save proficiency is informational");}}catch(RuntimeException ignored){}return out;}
    public static List<Stat> skills(JsonObject snapshot){var out=new ArrayList<Stat>();if(!text(snapshot,"profile").equals("srd_5_1"))return out;try{JsonObject scores=SrdAuthoring.data(snapshot.getAsJsonObject("sheet")).getAsJsonObject("abilities"),p=SheetSections.read(snapshot.getAsJsonObject("sheet"),"proficiencies");var proficient=lower(strings(p,"skills"));var expertise=lower(strings(p,"expertise"));SKILLS.entrySet().stream().sorted(Map.Entry.comparingByKey()).forEach(e->{int modifier=WizardModel.modifier(scores.get(e.getValue()).getAsInt());String key=e.getKey().toLowerCase(Locale.ROOT);String mark=expertise.contains(key)?" · recorded expertise":proficient.contains(key)?" · recorded proficiency":"";add(out,e.getKey(),signed(modifier)+" · "+e.getValue().toUpperCase(Locale.ROOT)+mark,"Base ability modifier; sheet proficiencies do not change automated combat");});}catch(RuntimeException ignored){}return out;}
    public record Check(String name,String ability,int base,int proficiency,int recordedAdjustment,boolean proficient,boolean expertise) {
        public int total(){return base+proficiency+recordedAdjustment;}
        public String display(){return signed(total());}
        public String breakdown(){return "Ability "+signed(base)+" + recorded proficiency "+proficiency+" + recorded adjustments "+signed(recordedAdjustment)+" = "+signed(total())+". This is an informational tabletop total; the combat engine does not consume recorded check proficiency or adjustments.";}
    }
    public static List<Check> checks(JsonObject snapshot,boolean saves){var out=new ArrayList<Check>();try{var r=rules(snapshot);int proficiency=r!=null?r.get("proficiency").getAsInt():SrdCharacterCodec.parseSheet(snapshot.getAsJsonObject("sheet").toString()).proficiency();var p=SheetSections.read(snapshot.getAsJsonObject("sheet"),"proficiencies");var prof=lower(strings(p,saves?"saves":"skills"));var expert=lower(strings(p,"expertise"));var names=new TreeMap<String,String>();if(saves)for(String key:ABILITIES)names.put(AbilityWorkspace.NAMES.get(key),key);else names.putAll(SKILLS);for(var e:names.entrySet()){String key=e.getKey().toLowerCase(Locale.ROOT);boolean trained=prof.contains(key)||saves&&prof.contains(e.getValue()),doubleProf=!saves&&trained&&expert.contains(key);int extra=0;for(var raw:array(p,"modifiers")){var m=raw.getAsJsonObject();if(text(m,"target").equalsIgnoreCase(e.getKey())||saves&&text(m,"target").equalsIgnoreCase(e.getValue()+" save"))extra+=m.get("value").getAsInt();}out.add(new Check(e.getKey(),e.getValue(),modifier(snapshot,e.getValue()),(doubleProf?2:trained?1:0)*proficiency,extra,trained||doubleProf,doubleProf));}}catch(RuntimeException unsupported){}return List.copyOf(out);}
    public static String header(JsonObject data,boolean library,boolean selected,boolean activeCombat){JsonObject identity=SheetSections.read(data.getAsJsonObject("sheet"),"identity");String role=library?"Personal library source":flag(data,"manager")?"Campaign character · DM view":text(data,"controller").isBlank()?"Campaign character":"Campaign character · "+(text(data,"controller").equals(text(data,"owner"))?"owner controlled":"assigned controller");String status=library?text(data,"stage"):(flag(data,"approved")?"approved":"awaiting approval")+(!text(data,"bound").isBlank()?" · bound":" · unbound")+(selected?" · selected":"")+(activeCombat?" · encounter active":"");return role+" · "+status+" · "+join(identity,"species",identity,"characterClass",identity,"subclass");}
    public static boolean editable(JsonObject data,boolean library,String self,boolean activeCombat){if(library)return true;return !activeCombat&&text(data,"bound").isEmpty()&&(flag(data,"manager")||text(data,"owner").equals(self));}
    public static boolean manualEditable(JsonObject data,boolean library,String self,boolean activeCombat){return editable(data,library,self,activeCombat);}
    public static String restriction(JsonObject data,boolean library,String self,boolean activeCombat){if(library)return "Personal library records use revision-safe section saves.";if(activeCombat)return "Read-only during an active encounter.";if(!text(data,"bound").isEmpty())return "Bound campaign characters keep manual and sheet edits read-only.";if(!flag(data,"manager")&&!text(data,"owner").equals(self))return "Controller access does not grant owner editing authority.";return "Campaign policy and server validation still decide each save; an edit may invalidate approval.";}
    public static List<String> strings(JsonObject section,String key){var out=new ArrayList<String>();for(var e:array(section,key))out.add(e.getAsString());return out;}
    private static void add(List<Stat> out,String label,String value,String authority){out.add(new Stat(label,value,authority));}
    private static String signed(int n){return n>=0?"+"+n:Integer.toString(n);}
    private static Set<String> lower(List<String> values){var out=new HashSet<String>();values.forEach(s->out.add(s.trim().toLowerCase(Locale.ROOT)));return out;}
    private static String full(String key){return switch(key){case "str"->"strength";case "dex"->"dexterity";case "con"->"constitution";case "int"->"intelligence";case "wis"->"wisdom";default->"charisma";};}
    private static String join(JsonObject a,String ak,JsonObject b,String bk,JsonObject c,String ck){return java.util.stream.Stream.of(text(a,ak),text(b,bk),text(c,ck)).filter(s->!s.isBlank()).reduce((x,y)->x+" · "+y).orElse("Identity details not recorded");}
}
